"<script>const $=id=>document.getElementById(id);let busy=false;function lock(v){busy=v;['submitPin','enable','start','stop','restart'].forEach(x=>$(x).disabled=v)}function err(t){$('error').textContent=t||'';$('error').style.display=t?'block':'none'}async function status(){try{const rs=await Promise.all([fetch('/api/remote/status',{cache:'no-store'}),fetch('/service/remote/_root/status',{cache:'no-store'})]);const j=await rs[0].json(),w=await rs[1].json();const online=!!j.service_online,rp=!!j.remoteplay_enabled,port=!!j.remoteplay_tcp_9295,pin=!!w.pairing_pin_ready,persist=!!w.registration_persisted;$('worker').textContent=j.worker_pid?('astrorem PID '+j.worker_pid):'OFFLINE';$('rpEnabled').textContent=rp?'HABILITADO':'DESATIVADO';$('rpPort').textContent=port?'RESPONDENDO':'SEM RESPOSTA';$('pairing').textContent=persist?'PAREADO':(pin?'PIN RECEBIDO':'NÃO PAREADO');$('account').textContent=w.pairing_account_id_ready?'IDENTIFICADA':'AGUARDANDO';$('persisted').textContent=persist?'SIM':'NÃO';$('servicePill').textContent=online?'WORKER ONLINE':'WORKER OFFLINE';$('servicePill').className='pill '+(online?'on':'bad');$('phasePill').textContent=(w.phase||j.phase||'idle').replaceAll('_',' ').toUpperCase();$('enable').style.display=rp?'none':'block';$('pairBox').style.display=persist?'none':'block';if(persist){$('screenTitle').textContent='Astro pareado ✓';$('screenText').textContent='O vínculo fica neste PS5. PC, celular e tablet só acessam o Astro.'}else if(pin){$('screenTitle').textContent='PIN recebido';$('screenText').textContent='Conta local identificada. O Astro está no estágio de registro do cliente Remote Play.'}else{$('screenTitle').textContent='Pareamento único';$('screenText').textContent='Pegue o PIN no próprio PS5 e digite no Astro. Você só faz isso uma vez.'}err('')}catch(e){err(String(e.message||e))}}async function act(path){if(busy)return;lock(true);err('');try{const r=await fetch(path,{method:'POST'});const j=await r.json();if(!r.ok)throw new Error((j.error||'Falha')+' rc='+(j.rc??'?'));await status()}catch(e){err(String(e.message||e));await status()}finally{lock(false)}}$('submitPin').onclick=()=>{const p=$('pin').value.trim();if(!/^\\d{8}$/.test(p)){err('Digite exatamente os 8 dígitos mostrados pelo PS5.');return;}act('/service/remote/_root/pairing/submit?pin='+encodeURIComponent(p))};$('enable').onclick=()=>act('/api/remote/enable');$('start').onclick=()=>act('/api/remote/start');$('stop').onclick=()=>act('/api/remote/stop');$('restart').onclick=()=>act('/api/remote/restart');status();setInterval(()=>{if(!busy)status()},1500);</script></body></html>";

